    /**
     * Restore one cPanel account from a backup.
     *
     * This function performs a full restoration of a single cPanel account from a `cpmove` tarball.
     *
     * Documented: Performs a full account restoration from a server-side cpmove archive or extracted directory.
     * overwrite=true may replace an existing account; deleteArchive=true deletes the source archive or directory after
     * restoration. This is not a local file upload.
     *
     * Documented: restricted is experimental and is not an effective security control. Restricted restores require
     * PostgreSQL 8.4 or newer for PostgreSQL databases, force unsupported shells to noshell, and skip invalid backup
     * parts with log warnings. A dedicated IP requires an available address.
     *
     * Documented: mailLocation accepts .local, .existing or a linked-node alias; failed existing/alias placement falls
     * back to .local. updateARecords controls all original-IP occurrences versus basic cPanel records. A transfer
     * session ID starts background work and does not prove restoration completion.
     *
     * API-map identity: whm1:start_local_cpmove_restore#GET (wire name start_local_cpmove_restore; Backup or Restore).
     *
     * @param string $cpmovepath A filepath that contains the account's `cpmove` tarball or the directory path that
     *     contains the extracted `cpmove` tarball.
     * @param bool|null $dedicatedIp Whether to assign the account a dedicated IP address. Null omits it.
     * @param bool|null $deleteArchive Whether to delete the `cpmove` tarball or extracted directory, given in the
     *     `cpmovepath` parameter, after the system completes the account restoration. Null omits it.
     * @param string|null $mailLocation The server on which the account's email will reside after the system completes
     *     the transfer. Null omits it.
     * @param bool|null $overwrite Whether to overwrite an existing account on the server, if one exists. Null omits it.
     * @param bool|null $restricted Whether to perform a restricted restore for the account. Null omits it.
     * @param 'all'|'basic'|null $updateARecords Whether to perform one of the following actions to the account's A
     *     records: * `all` - Replace all instances of the original server's IP address with the new server's IP
     *     address. Null omits it.
     * @param string|null $username The username to give to the restored cPanel account. Null omits it.
     * @return StartLocalCpmoveRestoreResult
     * @throws ApiException If transport, HTTP, the outcome, or the payload fails.
     * @throws PayloadMismatchException If the API reported success but the payload differs from the contract;
     *     any change the operation makes has already taken effect.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/backup-or-restore/transfers-start_local_cpmove_restore
     */
    public function startLocalCpmoveRestore(
        string $cpmovepath,
        ?bool $dedicatedIp = null,
        ?bool $deleteArchive = null,
        ?string $mailLocation = null,
        ?bool $overwrite = null,
        ?bool $restricted = null,
        ?string $updateARecords = null,
        ?string $username = null,
    ): array {
        /** @var StartLocalCpmoveRestoreResult $result Validated against BackupsSpec::START_LOCAL_CPMOVE_RESTORE. */
        $result = ($this->run)(BackupsSpec::START_LOCAL_CPMOVE_RESTORE, [
            'cpmovepath' => $cpmovepath,
            'dedicatedIp' => $dedicatedIp,
            'deleteArchive' => $deleteArchive,
            'mailLocation' => $mailLocation,
            'overwrite' => $overwrite,
            'restricted' => $restricted,
            'updateARecords' => $updateARecords,
            'username' => $username,
        ]);

        return $result;
    }

    /**
     * Enable or disable legacy backups.
     *
     * This function enables or disables legacy backups for a user.
     *
     * Documented: Toggles the selected account backup state and can enable or disable backups. Omitting legacy selects
     * the standard backup system; false is forwarded as 0. Returned toggle_status remains an integer 0/1 flag.
     *
     * Observed: Independent review on cPanel 11.138.0.19 returned success and toggle_status for an unknown user. A
     * successful toggle does not establish that the account exists.
     *
     * API-map identity: whm1:toggle_user_backup_state#GET (wire name toggle_user_backup_state; Backup Settings).
     *
     * @param string $user The cPanel account's username.
     * @param bool|null $legacy Whether the account should use the legacy backup system. Null omits it.
     * @return ToggleUserBackupStateResult
     * @throws ApiException If transport, HTTP, the outcome, or the payload fails.
     * @throws PayloadMismatchException If the API reported success but the payload differs from the contract;
     *     any change the operation makes has already taken effect.
     * @see https://api.docs.cpanel.net/specifications/whm.openapi/backup-settings/backup-toggle_user_backup_state
     */
    public function toggleUserBackupState(string $user, ?bool $legacy = null): array
    {
        /** @var ToggleUserBackupStateResult $result Validated against BackupsSpec::TOGGLE_USER_BACKUP_STATE. */
        $result = ($this->run)(BackupsSpec::TOGGLE_USER_BACKUP_STATE, ['user' => $user, 'legacy' => $legacy]);

        return $result;
    }
